import { readFile, writeFile } from "fs/promises";
import { createForks, teardownForks, type Forks } from "@tigrisdata/agent-kit";
import {
  S3Client,
  PutObjectCommand,
  ListObjectsV2Command,
} from "@aws-sdk/client-s3";

const TIGRIS_ENDPOINT = "REDACTED";

function normalizeBucketName(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
}

async function listKeys(client: S3Client, bucket: string): Promise<string[]> {
  const keys: string[] = [];
  let continuationToken: string | undefined = undefined;
  do {
    const resp = await client.send(
      new ListObjectsV2Command({
        Bucket: bucket,
        ContinuationToken: continuationToken,
      })
    );
    for (const obj of resp.Contents ?? []) {
      if (obj.Key) keys.push(obj.Key);
    }
    continuationToken = resp.IsTruncated ? resp.NextContinuationToken : undefined;
  } while (continuationToken);
  return keys.sort();
}

function arraysEqual(a: string[], b: string[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false;
  return true;
}

async function main(): Promise<void> {
  const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
  const sourceBucket = normalizeBucketName(`harbor-isolation-${trialId}`);

  const adminAccessKey = process.env.TIGRIS_STORAGE_ACCESS_KEY_ID;
  const adminSecretKey = process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY;
  if (!adminAccessKey || !adminSecretKey) {
    throw new Error(
      "TIGRIS_STORAGE_ACCESS_KEY_ID / TIGRIS_STORAGE_SECRET_ACCESS_KEY must be set"
    );
  }

  const adminClient = new S3Client({
    endpoint: TIGRIS_ENDPOINT,
    region: "REDACTED",
    credentials: {
      accessKeyId: adminAccessKey,
      secretAccessKey: adminSecretKey,
    },
  });

  const forkResp = await createForks(sourceBucket, 3, {
    prefix: "audit-fork",
    credentials: { role: "Editor" },
  });

  if (forkResp.error) {
    throw new Error(`createForks failed: ${forkResp.error.message ?? forkResp.error}`);
  }

  const forkSet: Forks = forkResp.data;

  try {
    if (forkSet.forks.length !== 3) {
      throw new Error(
        `Expected exactly 3 forks, got ${forkSet.forks.length}`
      );
    }

    // Per-fork S3 clients using each fork's own scoped credentials.
    const forkClients: S3Client[] = forkSet.forks.map((fork) => {
      if (!fork.credentials) {
        throw new Error(`Fork ${fork.bucket} is missing scoped credentials`);
      }
      return new S3Client({
        endpoint: TIGRIS_ENDPOINT,
        region: "REDACTED",
        credentials: {
          accessKeyId: fork.credentials.accessKeyId,
          secretAccessKey: fork.credentials.secretAccessKey,
        },
      });
    });

    // Parallel uploads, one per fork.
    await Promise.all(
      forkSet.forks.map((fork, idx) => {
        const key = `agent-${idx + 1}.out`;
        return forkClients[idx].send(
          new PutObjectCommand({
            Bucket: fork.bucket,
            Key: key,
            Body: `output of agent ${idx + 1}`,
            ContentType: "text/plain",
          })
        );
      })
    );

    // Audit: list source and each fork.
    const sourceKeys = await listKeys(adminClient, sourceBucket);
    const expectedSource = ["seed1.txt", "seed2.txt"];
    if (!arraysEqual(sourceKeys, expectedSource)) {
      throw new Error(
        `Source bucket ${sourceBucket} expected ${JSON.stringify(
          expectedSource
        )} but got ${JSON.stringify(sourceKeys)}`
      );
    }

    const forkResults: { bucket: string; keys: string[] }[] = [];
    for (let i = 0; i < forkSet.forks.length; i++) {
      const fork = forkSet.forks[i];
      const keys = await listKeys(forkClients[i], fork.bucket);
      forkResults.push({ bucket: fork.bucket, keys });

      const ownKey = `agent-${i + 1}.out`;
      const expected = [ownKey, "seed1.txt", "seed2.txt"].sort();
      if (!arraysEqual(keys, expected)) {
        throw new Error(
          `Fork bucket ${fork.bucket} expected ${JSON.stringify(
            expected
          )} but got ${JSON.stringify(keys)}`
        );
      }
      for (let j = 0; j < forkSet.forks.length; j++) {
        if (j === i) continue;
        const otherKey = `agent-${j + 1}.out`;
        if (keys.includes(otherKey)) {
          throw new Error(
            `Isolation violation: fork ${fork.bucket} contains ${otherKey} from another fork`
          );
        }
      }
    }

    const report = {
      source_keys: sourceKeys,
      fork_results: forkResults,
    };

    await writeFile(
      "/home/user/isolation/audit.json",
      JSON.stringify(report, null, 2),
      "utf-8"
    );

    console.log("Isolation audit completed successfully.");
    console.log(JSON.stringify(report, null, 2));
  } finally {
    const teardownResp = await teardownForks(forkSet);
    if (teardownResp.error) {
      console.error(
        `teardownForks failed: ${teardownResp.error.message ?? teardownResp.error}`
      );
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

