import { createBucket } from "@tigrisdata/storage";
import { S3Client, PutObjectCommand, HeadBucketCommand } from "@aws-sdk/client-s3";
import { readFile } from "fs/promises";

const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();
const sourceBucket = `harbor-isolation-${trialId}`.toLowerCase().replace(/[^a-z0-9.-]/g, "-");
console.log("Source bucket:", sourceBucket);

const s3 = new S3Client({
  endpoint: "REDACTED",
  region: "REDACTED",
  credentials: {
    accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
    secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
  },
});

let exists = false;
try {
  await s3.send(new HeadBucketCommand({ Bucket: sourceBucket }));
  exists = true;
} catch {}

if (!exists) {
  const c = await createBucket(sourceBucket, { enableSnapshot: true });
  console.log("createBucket result:", JSON.stringify(c, null, 2));
}

for (const k of ["seed1.txt", "seed2.txt"]) {
  await s3.send(new PutObjectCommand({
    Bucket: sourceBucket,
    Key: k,
    Body: `seed content for ${k}`,
  }));
  console.log("put", k);
}

